import { isRecord } from '../is-record.js';
import { parseJsonObject } from '../parse-json-object.js';
/**
 * Extracts a human-readable error message from a failed Functions HTTP API response.
 * Specific to the Functions API, whose error bodies are produced by its `src/util/response.js` `errorResponse` helper:
 *   { error: 'INVALID_INPUT', message: 'Validation error: ...', details?: { errors: [{ message }] } }
 */
export async function extractFunctionsApiErrorMessage(response) {
    const body = parseJsonObject(await response.text().catch(() => ''));
    if (typeof body?.message === 'string' && body.message)
        return body.message;
    const detailMessages = getDetailErrorMessages(body?.details);
    if (detailMessages.length > 0)
        return detailMessages.join('\n');
    if (typeof body?.error === 'string' && body.error)
        return body.error;
    return `HTTP ${response.status} ${response.statusText}`.trim();
}
function getDetailErrorMessages(details) {
    if (!isRecord(details) || !Array.isArray(details.errors))
        return [];
    return details.errors
        .map((e) => (isRecord(e) ? e.message : e))
        .filter((m) => typeof m === 'string' && m.length > 0);
}
